using System.Globalization;
using System.Text;
using System.Text.Json;
using System.Xml;
using System.Xml.Linq;
namespace PurpleStream;
record AccountInfo(string Status,string Expiry,int MaxConnections,string Timezone);
record EpgProgramme(string Title,string Description,DateTimeOffset Start,DateTimeOffset End,string ProviderStart="");
sealed class ProviderService:IDisposable {
 readonly Saved saved;readonly ProviderTransport transport;public AccountInfo Info{get;private set;}=new("Not connected","—",0,"UTC");
 public ProviderService(Saved settings,ProviderTransport? client=null){saved=settings;transport=client??new();}
 public string Base=>ProviderTransport.BaseServer(saved.Server);string Credentials=>"username="+Uri.EscapeDataString(saved.User)+"&password="+Uri.EscapeDataString(SettingsStore.Secret(saved));
 public async Task<JsonElement> Api(string action,CancellationToken token){var json=await transport.GetText(Base+"/player_api.php?"+Credentials+action,token).ConfigureAwait(false);return await Task.Run(()=>{using var doc=JsonDocument.Parse(json);return doc.RootElement.Clone();},token).ConfigureAwait(false);}
 public static string S(JsonElement e,string key,string fallback="")=>e.ValueKind==JsonValueKind.Object&&e.TryGetProperty(key,out var v)?v.ToString():fallback;
 public async Task<AccountInfo> Authenticate(CancellationToken token){var data=await Api("",token).ConfigureAwait(false);if(!data.TryGetProperty("user_info",out var user)||S(user,"auth").ToLowerInvariant() is not ("1" or "true"))throw new ProviderFailure("Login was rejected. Check your username, password and subscription.");string expiry="Not supplied";if(long.TryParse(S(user,"exp_date"),out long seconds)&&seconds>0&&seconds<253402300799)expiry=DateTimeOffset.FromUnixTimeSeconds(seconds).ToLocalTime().ToString("MMM dd, yyyy",CultureInfo.InvariantCulture);int.TryParse(S(user,"max_connections"),out int limit);string tz=data.TryGetProperty("server_info",out var server)?S(server,"timezone","UTC"):"UTC";return Info=new(S(user,"status","Connected"),expiry,limit,tz);}
 public async Task<List<Channel>> Catalog(string kind,CancellationToken token){var (action,categoryAction,path)=kind switch{"Live TV"=>("get_live_streams","get_live_categories","live"),"Movies"=>("get_vod_streams","get_vod_categories","movie"),_=>("get_series","get_series_categories","series")};var categories=new Dictionary<string,string>();using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(token)){deadline.CancelAfter(TimeSpan.FromSeconds(10));try{var data=await Api("&action="+categoryAction,deadline.Token).ConfigureAwait(false);if(data.ValueKind==JsonValueKind.Array)foreach(var entry in data.EnumerateArray())categories[S(entry,"category_id")]=S(entry,"category_name");}catch(OperationCanceledException)when(token.IsCancellationRequested){throw;}catch{}}
 var root=await Api("&action="+action,token).ConfigureAwait(false);if(root.ValueKind!=JsonValueKind.Array)throw new ProviderFailure("The provider returned an invalid catalog. Retry or use M3U fallback.");return await Task.Run(()=>{var result=new List<Channel>();foreach(var e in root.EnumerateArray()){token.ThrowIfCancellationRequested();string id=S(e,kind=="Series"?"series_id":"stream_id");if(id.Length==0)continue;string url=kind=="Series"?"series:"+id:MediaUrl(path,id,kind=="Live TV"?"ts":S(e,"container_extension","mp4"));int.TryParse(S(e,"tv_archive_duration"),out int days);result.Add(new(S(e,"name","Untitled"),url,categories.GetValueOrDefault(S(e,"category_id"),S(e,"category_id","Other")),kind,id,S(e,"country"),S(e,"epg_channel_id"),S(e,"tv_archive")=="1",days,GenreHint:S(e,"genre")));}return result;},token).ConfigureAwait(false);}
 string MediaUrl(string type,string id,string extension)=>Base+"/"+type+"/"+Uri.EscapeDataString(saved.User)+"/"+Uri.EscapeDataString(SettingsStore.Secret(saved))+"/"+id+"."+extension;
 public async Task<List<Channel>> Episodes(Channel series,CancellationToken token){var data=await Api("&action=get_series_info&series_id="+Uri.EscapeDataString(series.Id),token).ConfigureAwait(false);var result=new List<Channel>();if(data.TryGetProperty("episodes",out var seasons)&&seasons.ValueKind==JsonValueKind.Object)foreach(var season in seasons.EnumerateObject())if(season.Value.ValueKind==JsonValueKind.Array)foreach(var ep in season.Value.EnumerateArray()){string id=S(ep,"id");if(id.Length==0)continue;result.Add(new(S(ep,"title","Episode "+S(ep,"episode_num")),MediaUrl("series",id,S(ep,"container_extension","mp4")),series.Group,"Episode",id,series.CountryHint,GenreHint:series.GenreHint,Season:season.Name));}return result;}
 public async Task<List<Channel>> M3u(bool fallback,CancellationToken token){string text;Uri? origin=null;if(!fallback&&File.Exists(saved.Server))text=await File.ReadAllTextAsync(saved.Server,token).ConfigureAwait(false);else{string address=fallback?Base+"/get.php?"+Credentials+"&type=m3u_plus&output=ts":saved.Server;origin=new Uri(address);if(origin.Scheme is not ("http" or "https"))throw new ProviderFailure("Use an HTTP(S) playlist or choose a local M3U file.");text=await transport.GetText(address,token).ConfigureAwait(false);}string guide=Playlist.GuideUrl(text);if(saved.EpgUrl.Length==0&&guide.Length>0)saved.EpgUrl=Uri.TryCreate(guide,UriKind.Absolute,out var g)?g.AbsoluteUri:origin!=null?new Uri(origin,guide).AbsoluteUri:guide;return await Task.Run(()=>Playlist.Parse(text,origin),token).ConfigureAwait(false);}
 public async Task<List<EpgProgramme>> Guide(Channel channel,CancellationToken token){if(saved.Mode=="Xtream Codes"&&channel.Id.Length>0){JsonElement data;try{data=await Api("&action=get_simple_data_table&stream_id="+Uri.EscapeDataString(channel.Id),token).ConfigureAwait(false);}catch(ProviderFailure){data=await Api("&action=get_short_epg&stream_id="+Uri.EscapeDataString(channel.Id)+"&limit=100",token).ConfigureAwait(false);}var result=new List<EpgProgramme>();if(data.TryGetProperty("epg_listings",out var entries)&&entries.ValueKind==JsonValueKind.Array)foreach(var e in entries.EnumerateArray()){var start=ParseProviderTime(S(e,"start_timestamp"),S(e,"start"));var end=ParseProviderTime(S(e,"stop_timestamp"),S(e,"end"));if(end>start)result.Add(new(Decode(S(e,"title")),Decode(S(e,"description")),start,end,S(e,"start")));}return result.OrderBy(x=>x.Start).ToList();}
 if(string.IsNullOrWhiteSpace(saved.EpgUrl))throw new ProviderFailure("No EPG source is configured. Add an XMLTV URL in Settings, or use an Xtream provider that supplies a guide.");string xml=File.Exists(saved.EpgUrl)?await File.ReadAllTextAsync(saved.EpgUrl,token).ConfigureAwait(false):await transport.GetText(saved.EpgUrl,token).ConfigureAwait(false);return await Task.Run(()=>ParseXmlGuide(xml,channel),token).ConfigureAwait(false);}
 DateTimeOffset ParseProviderTime(string unix,string wall){if(long.TryParse(unix,out long t)&&t>0&&t<253402300799)return DateTimeOffset.FromUnixTimeSeconds(t);if(DateTime.TryParse(wall,CultureInfo.InvariantCulture,DateTimeStyles.None,out var local)){try{var zone=TimeZoneInfo.FindSystemTimeZoneById(Info.Timezone);return new DateTimeOffset(DateTime.SpecifyKind(local,DateTimeKind.Unspecified),zone.GetUtcOffset(local));}catch{return new DateTimeOffset(DateTime.SpecifyKind(local,DateTimeKind.Utc));}}return DateTimeOffset.MinValue;}
 static string Decode(string value){try{var bytes=Convert.FromBase64String(value);string decoded=new UTF8Encoding(false,true).GetString(bytes);return decoded.Any(char.IsControl)?value:decoded;}catch{return value;}}
 public static List<EpgProgramme> ParseXmlGuide(string xml,Channel channel){using var reader=XmlReader.Create(new StringReader(xml),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=100_000_000});var doc=XDocument.Load(reader);string id=channel.EpgId;if(id.Length==0)id=doc.Root?.Elements("channel").FirstOrDefault(c=>c.Elements("display-name").Any(n=>n.Value.Equals(channel.Name,StringComparison.OrdinalIgnoreCase)))?.Attribute("id")?.Value??"";if(id.Length==0)return new();var result=new List<EpgProgramme>();foreach(var e in doc.Root?.Elements("programme").Where(e=>(string?)e.Attribute("channel")==id)??Enumerable.Empty<XElement>()){if(TryXmlTime((string?)e.Attribute("start"),out var start)&&TryXmlTime((string?)e.Attribute("stop"),out var end)&&end>start)result.Add(new(e.Element("title")?.Value??"Untitled",e.Element("desc")?.Value??"",start,end));}return result.OrderBy(p=>p.Start).ToList();}
 static bool TryXmlTime(string? text,out DateTimeOffset time){time=default;if(string.IsNullOrWhiteSpace(text))return false;var chunks=text.Split(' ',StringSplitOptions.RemoveEmptyEntries);string offset=chunks.Length>1?chunks[1]:"+0000";if(offset.Length==5)offset=offset.Insert(3,":");return DateTimeOffset.TryParseExact(chunks[0]+" "+offset,"yyyyMMddHHmmss zzz",CultureInfo.InvariantCulture,DateTimeStyles.None,out time);}
 public Channel Catchup(Channel live,EpgProgramme programme){if(!live.HasArchive)throw new ProviderFailure("This channel does not advertise an archive.");if(programme.Start>=DateTimeOffset.UtcNow)throw new ProviderFailure("This programme has not aired yet.");if(live.ArchiveDays>0&&programme.Start<DateTimeOffset.UtcNow.AddDays(-live.ArchiveDays))throw new ProviderFailure("This programme is outside the provider's archive window.");long duration=Math.Max(60,(long)(programme.End-programme.Start).TotalSeconds);string url;
 if(live.CatchupSource.Length>0){url=live.CatchupSource.Replace("{utc}",programme.Start.ToUnixTimeSeconds().ToString()).Replace("{utcend}",programme.End.ToUnixTimeSeconds().ToString()).Replace("{duration}",duration.ToString());if(url.Contains('{'))throw new ProviderFailure("This M3U catch-up template uses an unsupported placeholder.");}
 else{string start=DateTime.TryParse(programme.ProviderStart,CultureInfo.InvariantCulture,DateTimeStyles.None,out var wall)?wall.ToString("yyyy-MM-dd:HH-mm",CultureInfo.InvariantCulture):TimeZoneInfo.ConvertTime(programme.Start,TimeZoneInfo.FindSystemTimeZoneById(Info.Timezone)).ToString("yyyy-MM-dd:HH-mm",CultureInfo.InvariantCulture);url=Base+"/timeshift/"+Uri.EscapeDataString(saved.User)+"/"+Uri.EscapeDataString(SettingsStore.Secret(saved))+"/"+Math.Ceiling(duration/60d).ToString(CultureInfo.InvariantCulture)+"/"+start+"/"+live.Id+".ts";}
 return live with{Name=live.Name+" — "+programme.Title,Url=url,Kind="Catch-up",HasArchive=false};}
 public void Dispose()=>transport.Dispose();
}
